from itertools import combinations
G={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
pieces=[]
for r in range(3):
 for c in range(6):
  box={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  for n in (3,4):
   for cells in combinations(box,n):
    s=set(cells)
    if s<=G: pieces.append((s,(r,c,n,tuple(sorted(box-s)) if n==3 else ())))
solutions=[]
def rec(rem,chosen):
 if not rem:
  solutions.append(chosen);return
 p=min(rem)
 for s,desc in pieces:
  if p in s and s<=rem:
   rec(rem-s,chosen+[desc])
rec(G,[])
print('n',len(solutions))
for sol in solutions[:50]: print(sol)

from itertools import combinations
inp=[[0,8,8,0,8,8,0],[8,8,8,8,8,8,0],[0,8,8,0,8,0,0],[0,0,8,8,8,0,0]]
# 4-connected components
G={(r,c) for r,row in enumerate(inp) for c,x in enumerate(row) if x==8}
comps=[]
while G:
 st=[next(iter(G))]; comp=set()
 while st:
  p=st.pop()
  if p not in G: continue
  G.remove(p);comp.add(p)
  r,c=p
  st += [(r+1,c),(r-1,c),(r,c+1),(r,c-1)]
 comps.append(comp)
print('components', [sorted(c) for c in comps])
# enumerate 2x2 blocks, each either full (color4) or 3 of 4 (remaining missing corner specifies 1-4)
for comp in comps:
 pieces=[]
 for r in range(3):
  for c in range(6):
   box={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
   for n in (3,4):
    for cells in combinations(box,n):
     s=set(cells)
     if s<=comp: pieces.append((s,(r,c,n,tuple(sorted(box-s)) if n==3 else ())))
 sols=[]
 def rec(rem,chosen):
  if not rem: sols.append(chosen);return
  p=min(rem)
  for s,d in pieces:
   if p in s and s<=rem: rec(rem-s,chosen+[d])
 rec(comp,[])
 print('sols',len(sols))
 for s in sols[:10]:print(s)

